function allTopics(){return [...topics,...state.created].map(t=>({...t,nodes:state.routes[t.id]||t.nodes}));}
function topic(){return allTopics().find(t=>t.id===state.activeTopic)||allTopics()[0];}
function node(id=selectedNode){return allTopics().flatMap(t=>t.nodes).find(n=>n.id===id);}
function nodeTopic(n){return allTopics().find(t=>t.id===n.topic);}
function nodeObjective(n){return n.objective??`能够独立解释「${n.title}」的核心概念，并完成一个实际练习。`;}
function siblings(t,parentId=null,stage=0){return t.nodes.filter(n=>(n.parentId||null)===parentId&&n.stage===stage).sort((a,b)=>(a.order??t.nodes.indexOf(a))-(b.order??t.nodes.indexOf(b)));}
function childrenOf(n,t=nodeTopic(n)){return siblings(t,n.id,n.stage);}
function descendants(n,t=nodeTopic(n)){return childrenOf(n,t).flatMap(child=>[child,...descendants(child,t)]);}
function orderedNodes(t){const walk=n=>[n,...childrenOf(n,t).flatMap(walk)];return t.stageTitles.flatMap((_,stage)=>siblings(t,null,stage).flatMap(walk));}
function leafNodes(t){const parents=new Set(t.nodes.map(n=>n.parentId).filter(Boolean));return orderedNodes(t).filter(n=>!parents.has(n.id));}
function nodeDepth(n){let depth=1;while(n.parentId){n=node(n.parentId);depth++;}return depth;}
function rawStatus(n){return state.statuses[n.id]||n.status;}
function statusOf(n){const children=childrenOf(n);if(!children.length)return rawStatus(n);const values=children.map(statusOf);if(values.every(s=>s==='done'))return 'done';if(values.includes('failed'))return 'failed';if(values.includes('pending'))return 'pending';return values.some(s=>s!=='idle')?'active':'idle';}
function completed(t){return leafNodes(t).filter(n=>statusOf(n)==='done').length;}
function percent(t){const count=leafNodes(t).length;return count?Math.round(completed(t)/count*100):0;}
function stageLeaves(t,stage){return leafNodes(t).filter(n=>n.stage===stage);}
function stageComplete(t,stage){const ns=stageLeaves(t,stage);return ns.length>0&&ns.every(n=>statusOf(n)==='done');}
function nextLearningNode(t){const ns=leafNodes(t);return ns.find(n=>statusOf(n)==='active')||ns.find(n=>statusOf(n)!=='done')||ns[0];}
function nextLeaf(n){const ns=leafNodes(nodeTopic(n));return ns[ns.findIndex(x=>x.id===n.id)+1];}
function editableNodes(t){state.routes[t.id]??=t.nodes.map((n,i)=>({...n,parentId:n.parentId||null,order:n.order??i,objective:nodeObjective(n),revision:n.revision||1}));return state.routes[t.id];}
function passedRecords(){const seen=new Set();return (state.assessments||[]).filter(r=>r.passed&&!seen.has(r.nodeId)&&seen.add(r.nodeId));}
function passedBefore(n){return (state.assessments||[]).some(r=>r.nodeId===n.id&&r.passed);}
function completionDate(n){return [...(state.assessments||[])].reverse().find(r=>r.nodeId===n.id&&r.passed&&r.revision===(n.revision||1))?.date||n.date||TODAY;}
function initializeHistory(){if(state.assessments!==null)return;state.assessments=[];allTopics().forEach(t=>t.nodes.forEach(n=>{if(n.status==='done'||state.checked.includes(n.id))state.assessments.push({id:crypto.randomUUID(),nodeId:n.id,topicId:t.id,title:n.title,objective:nodeObjective(n),revision:n.revision||1,date:n.date||TODAY,passed:true,score:null});}));save();}
function save(){localStorage.setItem(storageKey,JSON.stringify(state));}
