function latestDeletion(t){return state.deleted.filter(d=>d.topicId===t.id).at(-1);}
function routeUndo(t){const batch=latestDeletion(t);return batch?`<div class="route-undo" role="status">${I('info')}<div class="undo-copy"><strong>已删除「${esc(batch.nodes[0].title)}」及其子孙，共 ${batch.nodes.length} 个节点</strong><span>历史记录保留 · 刷新后仍可撤销 · 不会覆盖之后的编辑</span></div><button class="btn" data-undo-delete="${batch.id}">撤销删除</button></div>`:'';}
function undoDelete(batchId,confirmed=false){
 const batch=state.deleted.find(d=>d.id===batchId);if(!batch)return;
 const t=allTopics().find(t=>t.id===batch.topicId),parent=batch.parentId?node(batch.parentId):null;
 const goalChanged=parent&&(parent.revision||1)!==batch.parentRevision;
 if(parent&&!confirmed&&(goalChanged||(!childrenOf(parent).length&&rawStatus(parent)!=='idle'))){setModal(modalFrame('恢复子节点并重新汇总？',esc(parent.title),`<div class="modal-body"><p>${goalChanged?'删除后父节点目标或结构已改变，恢复的子节点需重新检验，不能直接继承旧成绩。':'父节点已产生新的学习进度；恢复子节点后，父节点将仅汇总子节点，不再单独计入完成。'} 历史检验和打卡仍会保留。</p></div>`,`<button class="btn" data-action="close-modal">暂不恢复</button><button class="btn primary" data-confirm-undo="${batchId}">确认恢复</button>`));return;}
 const list=editableNodes(t),root=batch.nodes[0],peers=siblings({...t,nodes:list},batch.parentId,batch.stage);let position=peers.findIndex(n=>n.id===batch.nextId);
 if(position<0){const previous=peers.findIndex(n=>n.id===batch.previousId);position=previous<0?peers.length:previous+1;}
 if(parent&&!childrenOf(parent).length)invalidateProgress(list.find(n=>n.id===parent.id),'恢复子节点后，父节点仅汇总子节点进度。');
 if(goalChanged)batch.nodes.forEach(n=>{invalidateProgress(n,'上级目标已改变，恢复后需重新检验。');n.customContent=true;});
 list.push(...batch.nodes);peers.splice(position,0,root);peers.forEach((n,i)=>{n.order=i;});state.deleted=state.deleted.filter(d=>d.id!==batchId);save();closeModal();refreshRoute(root.id);toast('删除已撤销，节点、笔记与资源已恢复。');
}
function moveNode(id,direction){const n=node(id),t=nodeTopic(n),peers=siblings(t,n.parentId||null,n.stage),i=peers.findIndex(x=>x.id===id),target=peers[i+direction];if(target)reorderNode(id,target.id,direction>0);}
function reorderNode(id,targetId,after){
 const n=node(id),target=node(targetId);if(!n||!target||id===targetId)return;
 if(n.topic!==target.topic||n.stage!==target.stage||(n.parentId||null)!==(target.parentId||null)){toast('只能在同一阶段、同一父节点下排序，不能拖成子节点或跨组移动。');return;}
 const t=nodeTopic(n),list=editableNodes(t),peers=siblings({...t,nodes:list},n.parentId||null,n.stage).filter(x=>x.id!==id),position=peers.findIndex(x=>x.id===targetId)+(after?1:0);
 peers.splice(position,0,list.find(x=>x.id===id));peers.forEach((x,i)=>{x.order=i;});save();refreshRoute(id);toast('同级顺序已更新，子节点随父节点整体移动。');
}
function nodeHistory(n){const records=(state.assessments||[]).filter(r=>r.nodeId===n.id);if(!records.length)return '';return `<details class="node-history"><summary>历史检验记录（${records.length} 条）</summary>${records.slice().reverse().map(r=>`<div class="history-entry"><strong>${esc(r.date)} · 第 ${r.revision} 版 · ${r.passed?'通过':'未通过'}${r.score===null?'':` · ${r.score} / 3`}</strong><p>${esc(r.objective)}</p>${r.revision!==(n.revision||1)?'<small>旧版记录，仅作回顾，不代表当前目标已掌握。</small>':''}</div>`).join('')}</details>`;}
