 if(nodeEditor&&document.getElementById('node-editor-form')){const draft=editorValues();if(JSON.stringify(draft)!==JSON.stringify(nodeEditor.original)){nodeEditor.draft=draft;setModal(modalFrame('放弃未保存的修改？','学习节点还没有保存。','<div class="modal-body"><p>可以继续编辑，或放弃这次修改；原节点与学习记录不会改变。</p></div>','<button class="btn" data-action="resume-node-edit">继续编辑</button><button class="btn danger" data-action="discard-node-edit">放弃修改</button>'));return;}nodeEditor=null;}
