function showSearch(){setModal(modalFrame('搜索学习节点','找到想回顾的知识，再向前一步。',`<div class="modal-body"><label for="node-search" class="small muted">节点名称或主题名称</label><input id="node-search" class="search-input" style="margin-top:8px" placeholder="搜索，例如：面向对象、集合、英语"><div class="search-results" id="search-results"></div></div>`));search('');document.getElementById('node-search').focus();}
function search(value){const matches=allTopics().flatMap(t=>t.nodes.map(n=>({...n,topicTitle:t.title}))).filter(n=>(n.title+n.topicTitle).toLowerCase().includes(value.toLowerCase())).slice(0,7);document.getElementById('search-results').innerHTML=matches.length?matches.map(n=>`<button class="search-result" data-go="node/${n.id}"><span>${esc(n.title)}<span class="small" style="display:block;margin-top:4px">${esc(n.topicTitle)}</span></span>${badge(statusOf(n))}</button>`).join(''):'<p class="search-empty">没有找到相关节点，试试更简短的关键词。</p>';}
function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
function persistNote(){const el=document.getElementById('note-editor');if(!el)return;state.notes[selectedNode]=el.value;save();const indicator=document.getElementById('save-status');if(indicator)indicator.innerHTML=`${I('check','sm')}已保存到本机`;}
function render(){clearTimeout(timer);clearTimeout(notesTimer);nodeEditor=null;document.getElementById('portal').innerHTML='';document.getElementById('app').inert=false;document.body.style.overflow='';const route=currentRoute();const base=route.split('/')[0];const app=document.getElementById('app');if(base==='node'){selectedNode=route.split('/')[1]||'j5';const n=node();if(!n){app.innerHTML=shell('<section class="card empty-state"><h1>这个节点已从路线移除</h1><p>可以回到学习路线撤销最近删除；历史打卡不受影响。</p><button class="btn primary" data-go="roadmap">返回学习路线</button></section>','节点已移除','roadmap');document.getElementById('main')?.focus();return;}state.activeTopic=n.topic;if(!childrenOf(n).length&&statusOf(n)==='idle')state.statuses[selectedNode]='active';save();}if(['quiz','quiz-loading','success','failure'].includes(base)&&(!node()||childrenOf(node()).length)){navTo(node()?'node/'+selectedNode:'roadmap');return;}let html;
 if(base==='login'||base==='register')html=auth(base==='register');else if(base==='create'||base==='generating'||base==='generated')html=creation(base);else if(base==='roadmap')html=roadmap();else if(base==='node'||['quiz','quiz-loading','success','failure'].includes(base))html=nodePage();else if(base==='stats'||base==='review')html=statistics();else html=dashboard(base==='empty');app.innerHTML=html;window.scrollTo(0,0);const label=screens.find(s=>s[0]===route)?.[2]||'知序';document.title=`${label} · 知序 Pathly`;
 if(base==='generating'&&!new URLSearchParams(location.search).has('capture'))timer=setTimeout(()=>navTo('generated'),5000);
 if(base==='quiz-loading'){setModal(quizModal('quiz-loading'));if(!new URLSearchParams(location.search).has('capture'))timer=setTimeout(()=>navTo('quiz'),2800);}
 if(base==='quiz')setModal(quizModal());if(base==='success'||base==='failure')setModal(resultModal(base==='success',quiz.results.length!==3));if(base==='review'){if(stageComplete(allTopics().find(t=>t.id==='java'),0))setModal(reviewModal());else{navTo('stats');toast('当前阶段尚未全部通过检验，完成后再查看复盘。');}}
 if(!['quiz','quiz-loading','success','failure','review'].includes(base))document.getElementById('main')?.focus({preventScroll:true});
}
function updateWizard(){const title=document.getElementById('topic-title');if(title){wizard.title=title.value;wizard.goal=document.getElementById('learning-goal').value;wizard.hours=Number(document.getElementById('hours').value);}}
function startQuiz(retry=false){persistNote();const n=node();if(!n||childrenOf(n).length){toast('父节点仅汇总进度，请进入叶子节点发起检验。');return;}quiz={index:0,answers:[],results:[],feedback:null,selected:null,wasComplete:statusOf(n)==='done',hadPassed:passedBefore(n),revision:n.revision||1,nodeId:n.id};if(!quiz.wasComplete){state.statuses[selectedNode]='pending';save();}navTo(retry?'quiz':'quiz-loading');}
function submitAnswer(){const q=questions()[quiz.index];let answer=q.options?quiz.selected:document.getElementById('quiz-answer').value;if(answer===null||typeof answer==='string'&&!answer.trim()){toast('请先写下你的答案，再提交检验。');return;}quiz.selected=answer;const correct=q.options?answer===q.correct:q.validate(answer);quiz.answers[quiz.index]=answer;quiz.results[quiz.index]=correct;quiz.feedback={correct};setModal(quizModal());}
function nextQuestion(){if(quiz.index<2){quiz.index++;quiz.selected=null;quiz.feedback=null;setModal(quizModal());return;}const n=node();if(!n||childrenOf(n).length||(quiz.revision&&quiz.revision!==(n.revision||1))){navTo('roadmap');toast('节点目标或结构已改变，请重新发起检验。');return;}const score=quiz.results.filter(Boolean).length,success=score>=2;quiz.hadPassed=passedBefore(n);state.assessments.push({id:crypto.randomUUID(),nodeId:n.id,topicId:n.topic,title:n.title,objective:nodeObjective(n),revision:n.revision||1,date:TODAY,passed:success,score,answers:quiz.answers});if(statusOf(n)!=='done'){state.statuses[n.id]=success?'done':'failed';if(success&&!quiz.hadPassed&&!state.checked.includes(n.id))state.checked.push(n.id);}save();navTo(success?'success':'failure');}
function resetDemo(){setModal(modalFrame('重置演示记录？','这只会清除当前浏览器内的原型学习记录。',`<div class="modal-body"><p class="muted" style="font-size:12px">你添加的笔记、资源、主题和检验结果都会恢复为初始示例。原型之外的数据不受影响。</p></div>`,`<button class="btn" data-action="close-modal">保留记录</button><button class="btn danger" data-action="confirm-reset">确认重置</button>`));}
document.addEventListener('click',event=>{
 const target=event.target.closest('button,a,[data-topic]');if(!target)return;
 if(target.classList.contains('skip-link')){event.preventDefault();document.getElementById('main')?.focus();return;}
 if(target.dataset.nodeActions){showNodeActions(target.dataset.nodeActions);return;}
 if(target.dataset.editNode){showNodeEditor({id:target.dataset.editNode,topicId:node(target.dataset.editNode).topic});return;}
 if(target.dataset.addChild){const parent=node(target.dataset.addChild);showNodeEditor({parentId:parent.id,topicId:parent.topic});return;}
 if(target.dataset.addStage!==undefined){showNodeEditor({stage:Number(target.dataset.addStage)});return;}
 if(target.dataset.deleteNode){showDeleteNode(target.dataset.deleteNode);return;}
 if(target.dataset.confirmDelete){deleteNode(target.dataset.confirmDelete);return;}
 if(target.dataset.undoDelete){undoDelete(target.dataset.undoDelete);return;}
 if(target.dataset.confirmUndo){undoDelete(target.dataset.confirmUndo,true);return;}
 if(target.dataset.moveNode){moveNode(target.dataset.moveNode,Number(target.dataset.direction));return;}
 if(target.dataset.toggleNode){const id=target.dataset.toggleNode,on=!collapsedNodes.has(id);if(on)collapsedNodes.add(id);else collapsedNodes.delete(id);document.getElementById('children-'+id).hidden=on;target.setAttribute('aria-expanded',String(!on));target.setAttribute('aria-label',(on?'展开':'收起')+'：'+node(id).title);target.innerHTML=I(on?'chevron':'down','sm');return;}
 if(target.dataset.go){event.preventDefault();persistNote();navTo(target.dataset.go);return;}
 if(target.dataset.preview){event.preventDefault();quiz={index:0,answers:[],results:[],feedback:null,selected:null};selectedNode='j5';state.activeTopic='java';routeTab='route';filter='all';navTo(target.dataset.preview);return;}
 if(target.dataset.topic){event.preventDefault();openTopic(target.dataset.topic);return;}
 if(target.dataset.level){updateWizard();wizard.level=target.dataset.level;document.querySelectorAll('[data-level]').forEach(el=>{const selected=el.dataset.level===wizard.level;el.classList.toggle('selected',selected);el.setAttribute('aria-checked',String(selected));});return;}
 if(target.dataset.preset){updateWizard();wizard.title=target.dataset.preset;wizard.goal=/设计/.test(wizard.title)?'掌握以用户为中心的设计流程，独立完成一份包含研究、原型与视觉稿的产品设计案例。':/英语/.test(wizard.title)?'能够在工作与生活中自信交流，用英语完成五分钟的主题分享与日常面试。':'能够独立使用 Spring Boot 开发 RESTful API，完成一个可部署的个人项目。';navTo('create');return;}
 if(target.dataset.routeTab){routeTab=target.dataset.routeTab;render();return;}
 if(target.dataset.review!==undefined){const stage=Number(target.dataset.review);if(stageComplete(topic(),stage))setModal(reviewModal(stage,topic()));return;}
 if(target.dataset.answer!==undefined&&!quiz.feedback){quiz.selected=Number(target.dataset.answer);document.querySelectorAll('[data-answer]').forEach(el=>{const on=Number(el.dataset.answer)===quiz.selected;el.classList.toggle('selected',on);el.setAttribute('aria-checked',String(on));});document.querySelector('[data-action="submit-answer"]').disabled=false;return;}
 if(target.dataset.heat){const date=target.dataset.heat;const count=getActivity()[date]||0;const message=`${date} · ${count?count+' 个节点通过检验':'没有打卡记录，积累需要时间'}`;if(document.getElementById('heat-selection'))document.getElementById('heat-selection').textContent=message;else toast(message);return;}
 if(target.dataset.format){const area=document.getElementById('note-editor');const s=area.selectionStart,e=area.selectionEnd;const text=area.value.slice(s,e);const inserts={heading:`## ${text||'新标题'}`,bold:`**${text||'重点内容'}**`,italic:`*${text||'强调内容'}*`,list:`- ${text||'学习要点'}`,code:'`'+(text||'代码')+'`',link:`[${text||'资源名称'}](链接地址)`};area.setRangeText(inserts[target.dataset.format],s,e,'end');area.dispatchEvent(new Event('input',{bubbles:true}));area.focus();return;}
 const action=target.dataset.action;if(!action)return;event.preventDefault();
 if(action==='resume-node-edit'){showNodeEditor(nodeEditor);return;}
 if(action==='discard-node-edit'){nodeEditor=null;closeModal();return;}
 if(action==='guide')showGuide();else if(action==='close-modal')closeModal();else if(action==='add-resource')showAddResource();else if(action==='search')showSearch();else if(action==='start-quiz')startQuiz();else if(action==='retry-quiz')startQuiz(true);else if(action==='submit-answer')submitAnswer();else if(action==='next-question')nextQuestion();else if(action==='filter'){filter=filter==='all'?'unfinished':'all';render();}else if(action==='next-node'){const t=allTopics().find(t=>t.nodes.some(n=>n.id===selectedNode));const next=nextLeaf(node());navTo(next?'node/'+next.id:'roadmap');}else if(action==='toggle-password'){const input=document.getElementById('auth-password');input.type=input.type==='password'?'text':'password';target.setAttribute('aria-label',input.type==='password'?'显示密码':'隐藏密码');}else if(action==='forgot'){setModal(modalFrame('找回密码','当前是交互演示，不涉及真实账户。',`<div class="modal-body"><p class="muted" style="font-size:12px;line-height:2">正式产品会通过注册邮箱发送重置链接。体验原型无需找回密码，可以直接进入示例工作台。</p></div>`,`<button class="btn" data-action="close-modal">返回登录</button><button class="btn primary" data-go="dashboard">体验工作台</button>`));}else if(action==='terms'){setModal(modalFrame('演示服务与隐私说明','知序 Pathly · 高保真交互原型',`<div class="modal-body"><p style="line-height:2;font-size:12px;color:var(--muted)">本原型不创建真实账号，不发送、记录或保存邮箱与密码。笔记、资源与学习进度仅存储于当前浏览器。AI 规划与检验由本地预设数据与简单规则模拟，不构成真实能力评估。请勿填写个人敏感信息。</p></div>`,`<small>所有数据均可通过原型导览重置。</small><button class="btn primary" data-action="close-modal">我知道了</button>`));}else if(action==='heat-today'){document.querySelector(`[data-heat="${TODAY}"]`)?.click();document.querySelector(`[data-heat="${TODAY}"]`)?.focus();}else if(action==='open-review'){state.activeTopic='java';navTo('review');}else if(action==='reset-demo')resetDemo();else if(action==='confirm-reset'){state=structuredClone(baseline);collapsedNodes.clear();initializeHistory();save();navTo('dashboard');toast('演示数据已恢复，开始新一轮探索吧。');}else if(action==='confirm-create'){
 const template=wizardTemplate();const id='custom-'+Date.now();const t={id,title:wizard.title,subtitle:wizard.goal,goal:wizard.goal,hours:wizard.hours,level:wizard.level,icon:template.icon,color:template.color,weeks:Math.max(3,Math.round(template.weeks*8/wizard.hours)),total:template.nodes.length,stageTitles:template.stageTitles,stageWeeks:template.stageWeeks,nodes:template.nodes.map((n,i)=>({...n,id:id+'-'+i,topic:id,status:'idle',date:''})),next:template.nodes[0].title,current:id+'-0'};state.created.push(t);state.activeTopic=id;save();navTo('roadmap');toast('路线已加入工作台，从第一个小目标开始吧。');
 }
});
document.addEventListener('input',event=>{
 if(event.target.closest('#node-editor-form')){updateNodeImpact();if(event.target.id==='edit-node-objective')document.getElementById('ack-node-impact').checked=false;}
 if(event.target.id==='note-editor'){const area=event.target;state.notes[selectedNode]=area.value;save();document.getElementById('save-status').textContent='正在保存…';document.getElementById('note-count').textContent=area.value.length+' 字';clearTimeout(notesTimer);notesTimer=setTimeout(persistNote,450);}
 if(event.target.id==='hours'){wizard.hours=Number(event.target.value);document.getElementById('hours-value').textContent=wizard.hours;}
 if(event.target.id==='quiz-answer'){quiz.selected=event.target.value;const btn=document.querySelector('[data-action="submit-answer"]');if(btn)btn.disabled=!event.target.value.trim();}
 if(event.target.id==='node-search')search(event.target.value);
});
document.addEventListener('submit',event=>{
 event.preventDefault();
 if(event.target.id==='node-editor-form'){submitNodeEditor();return;}
 if(event.target.id==='create-form'){updateWizard();if(!wizard.title.trim()||wizard.goal.trim().length<10){document.getElementById('create-error').textContent='请填写主题，并用至少 10 个字描述你的学习目标。';document.getElementById(!wizard.title.trim()?'topic-title':'learning-goal').focus();return;}wizard.title=wizard.title.trim();navTo('generating');}
 if(event.target.id==='auth-form'){const reg=currentRoute()==='register';const pw=document.getElementById('auth-password').value;if(reg&&(!/[A-Za-z]/.test(pw)||!/[0-9]/.test(pw))){document.getElementById('auth-error').textContent='密码需要同时包含字母和数字。演示时请勿使用真实密码。';document.getElementById('auth-password').focus();return;}if(reg){state.name=document.getElementById('auth-name').value.trim()||'新同学';save();}const btn=event.target.querySelector('[type=submit]');btn.disabled=true;btn.innerHTML=I('loading','spinner sm')+'正在进入你的学习空间…';timer=setTimeout(()=>{navTo(reg?'empty':'dashboard');toast(reg?'演示账号已就绪，创建你的第一个学习主题吧。':'欢迎回来，今天也继续前进。');},550);}
 if(event.target.id==='resource-form'){let url;try{url=new URL(document.getElementById('resource-url').value);if(!['http:','https:'].includes(url.protocol))throw new Error();}catch{document.getElementById('resource-error').textContent='请输入有效的 http:// 或 https:// 链接。';document.getElementById('resource-url').focus();return;}const title=document.getElementById('resource-title').value.trim();if(!title){document.getElementById('resource-error').textContent='请为资源填写一个名称。';return;}const existing=resourcesFor(node());if(existing.some(r=>r.url===url.href)){document.getElementById('resource-error').textContent='这个链接已经收藏过了，可以在资源列表中查看。';return;}state.resources[selectedNode]=[...existing,{title,url:url.href,type:document.getElementById('resource-type').value}];save();closeModal();render();toast('资源已收藏，下次学习时一眼就能找到。');}
});
document.addEventListener('keydown',event=>{
 const modal=document.querySelector('#portal [role="dialog"]');if(event.key==='Escape'&&modal){event.preventDefault();closeModal();return;}
 if(event.key==='Tab'&&modal){const focusables=[...modal.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),textarea,select,[tabindex="0"]')].filter(el=>el.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first?.focus();}}
 if((event.key==='Enter'||event.key===' ')&&event.target.matches('[role="link"][data-topic]')){event.preventDefault();openTopic(event.target.dataset.topic);}
});
function clearDropMarkers(){document.querySelectorAll('.drop-before,.drop-after').forEach(el=>el.classList.remove('drop-before','drop-after'));}
document.addEventListener('dragstart',event=>{const handle=event.target.closest('[data-drag-node]');if(!handle)return;draggedNodeId=handle.dataset.dragNode;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',draggedNodeId);handle.closest('.node-branch').classList.add('is-dragging');});
document.addEventListener('dragover',event=>{if(!draggedNodeId)return;const card=event.target.closest('[data-card-id]');clearDropMarkers();if(!card)return;event.preventDefault();const n=node(draggedNodeId),target=node(card.dataset.cardId);const allowed=n.id!==target.id&&n.topic===target.topic&&n.stage===target.stage&&(n.parentId||null)===(target.parentId||null);event.dataTransfer.dropEffect=allowed?'move':'none';if(allowed)card.classList.add(event.clientY>card.getBoundingClientRect().top+card.offsetHeight/2?'drop-after':'drop-before');});
document.addEventListener('drop',event=>{if(!draggedNodeId)return;event.preventDefault();const card=event.target.closest('[data-card-id]'),id=draggedNodeId;draggedNodeId=null;clearDropMarkers();if(card)reorderNode(id,card.dataset.cardId,event.clientY>card.getBoundingClientRect().top+card.offsetHeight/2);});
document.addEventListener('dragend',()=>{draggedNodeId=null;clearDropMarkers();document.querySelectorAll('.is-dragging').forEach(el=>el.classList.remove('is-dragging'));});
window.addEventListener('hashchange',render);
window.addEventListener('pagehide',persistNote);
initializeHistory();
render();
